#include <stddef.h>
#include <stdint.h>

#define TRACE_BUF_CAP 1024u

typedef struct {
    uint32_t events[TRACE_BUF_CAP];
    uint32_t head;
    uint32_t count;
} TraceBuffer;

int trace_record(TraceBuffer *tb, uint32_t event)
{
    if (tb == NULL) {
        return -1;
    }

    if (tb->count < TRACE_BUF_CAP) {
        /* 尾部下标 = head + count，对容量取模保证不越界 */
        tb->events[(tb->head + tb->count) % TRACE_BUF_CAP] = event;
        tb->count++;
        return 0;
    }

    /* 已写满：覆盖最旧事件（head 所在位置），并让 head 前移一格 */
    tb->events[tb->head] = event;
    tb->head = (tb->head + 1u) % TRACE_BUF_CAP;
    return 1;
}
